import csv
import io
import json

_FIELDS = ("id", "name")


def _normalize(rows):
    """Materialize rows once, picking only id and name.

    Missing or None values become ''; other values are stringified.
    Order is preserved and inputs are not mutated, so one-shot
    iterables are supported.
    """
    return [
        {key: "" if row.get(key) is None else str(row[key]) for key in _FIELDS}
        for row in rows
    ]


def export_rows(rows, format):
    if format == "csv":
        buffer = io.StringIO(newline="")
        writer = csv.writer(buffer, lineterminator="\n")
        writer.writerow(_FIELDS)
        for row in _normalize(rows):
            writer.writerow([row[key] for key in _FIELDS])
        return buffer.getvalue()
    if format == "json":
        return json.dumps(_normalize(rows), ensure_ascii=False, separators=(",", ":"))
    raise ValueError("unsupported format")

